{
 "description": "MonitorV2 is the Schema for the MonitorV2s API. Manages a V2 monitor resource within OpenStack.",
 "properties": {
  "spec": {
   "description": "MonitorV2Spec defines the desired state of MonitorV2",
   "properties": {
    "deletionPolicy": {
     "default": "Delete",
     "description": "DeletionPolicy specifies what will happen to the underlying external\nwhen this managed resource is deleted - either \"Delete\" or \"Orphan\" the\nexternal resource.\nThis field is planned to be deprecated in favor of the ManagementPolicies\nfield in a future release. Currently, both could be set independently and\nnon-default values would be honored if the feature flag is enabled.\nSee the design doc for more information: https://github.com/crossplane/crossplane/blob/499895a25d1a1a0ba1604944ef98ac7a1a71f197/design/design-doc-observe-only-resources.md?plain=1#L223",
     "enum": [
      "Orphan",
      "Delete"
     ],
     "type": "string"
    },
    "forProvider": {
     "properties": {
      "adminStateUp": {
       "description": "The administrative state of the monitor.\nA valid value is true (UP) or false (DOWN).",
       "type": "boolean"
      },
      "delay": {
       "description": "The time, in seconds, between sending probes to members.",
       "type": "number"
      },
      "domainName": {
       "description": "The domain name to use in the HTTP host header\nhealth monitor requests. Supported in Octavia API version 2.10 or later.",
       "type": "string"
      },
      "expectedCodes": {
       "description": "Required for HTTP(S) types. Expected HTTP codes\nfor a passing HTTP(S) monitor. You can either specify a single status like\n\"200\", a list like \"200, 202\" or a range like \"200-202\". Default is \"200\".",
       "type": "string"
      },
      "httpMethod": {
       "description": "Required for HTTP(S) types. The HTTP method that\nthe health monitor uses for requests. One of CONNECT, DELETE, GET, HEAD,\nOPTIONS, PATCH, POST, PUT, or TRACE. The default is GET.",
       "type": "string"
      },
      "httpVersion": {
       "description": "Required for HTTP(S) types. The HTTP version that\nthe health monitor uses for requests. One of 1.0 or 1.1is supported for HTTP(S) monitors. The default is1.0`. Supported in Octavia API version\n2.10 or later.",
       "type": "string"
      },
      "maxRetries": {
       "description": "Number of permissible ping failures before\nchanging the member's status to INACTIVE. Must be a number between 1\nand 10.",
       "type": "number"
      },
      "maxRetriesDown": {
       "description": "Number of permissible ping failures before\nchanging the member's status to ERROR. Must be a number between 1 and 10.\nThe default is 3. Changing this updates the max_retries_down of the\nexisting monitor.",
       "type": "number"
      },
      "name": {
       "description": "The Name of the Monitor.",
       "type": "string"
      },
      "poolId": {
       "description": "The id of the pool that this monitor will be assigned to.",
       "type": "string"
