       "description": "The region in which to obtain the V2 Networking client.\nA Networking client is needed to create a monitor. If omitted, the\nregion argument of the provider is used. Changing this creates a new\nmonitor.",
       "type": "string"
      },
      "tenantId": {
       "description": "Required for admins. The UUID of the tenant who owns\nthe monitor.  Only administrative users can specify a tenant UUID\nother than their own. Changing this creates a new monitor.",
       "type": "string"
      },
      "timeout": {
       "description": "Maximum number of seconds for a monitor to wait for a\nping reply before it times out. The value must be less than the delay\nvalue.",
       "type": "number"
      },
      "type": {
       "description": "The type of probe, which is PING, TCP, HTTP, HTTPS,\nTLS-HELLO, SCTP or UDP-CONNECT, that is sent by the loadbalancer to\nverify the member state. Changing this creates a new monitor.",
       "type": "string"
      },
      "urlPath": {
       "description": "Required for HTTP(S) types. URI path that will be\naccessed if monitor type is HTTP or HTTPS. Default is /.",
       "type": "string"
      }
